PRAGMA foreign_keys = ON;
PRAGMA user_version = 2;
CREATE TABLE IF NOT EXISTS classes(class_id TEXT PRIMARY KEY, class_name TEXT NOT NULL, grade INTEGER NOT NULL CHECK(grade>0), synthetic INTEGER NOT NULL CHECK(synthetic=1));
CREATE TABLE IF NOT EXISTS students(student_id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes, display_alias TEXT NOT NULL, synthetic INTEGER NOT NULL CHECK(synthetic=1));
CREATE TABLE IF NOT EXISTS knowledge_points(kp_id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS questions(question_id TEXT PRIMARY KEY, kp_id TEXT NOT NULL REFERENCES knowledge_points, question_type TEXT NOT NULL, difficulty TEXT NOT NULL CHECK(difficulty IN ('easy','medium','hard')), max_score REAL NOT NULL CHECK(max_score>0), rubric_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(task_id TEXT PRIMARY KEY, task_type TEXT NOT NULL, available_at TEXT NOT NULL, due_at TEXT NOT NULL CHECK(due_at>=available_at), comparison_group TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS task_questions(task_id TEXT NOT NULL REFERENCES tasks, question_id TEXT NOT NULL REFERENCES questions, question_order INTEGER NOT NULL CHECK(question_order>0), PRIMARY KEY(task_id,question_id), UNIQUE(task_id,question_order));
CREATE TABLE IF NOT EXISTS task_assignments(task_id TEXT NOT NULL REFERENCES tasks, student_id TEXT NOT NULL REFERENCES students, assigned_at TEXT NOT NULL, eligibility_status TEXT NOT NULL CHECK(eligibility_status IN ('eligible','exempt')), PRIMARY KEY(task_id,student_id));
CREATE TABLE IF NOT EXISTS responses(response_id TEXT PRIMARY KEY, student_id TEXT NOT NULL, task_id TEXT NOT NULL, question_id TEXT NOT NULL, attempt_no INTEGER NOT NULL CHECK(attempt_no>=1), submitted_at TEXT NOT NULL, score REAL CHECK(score>=0), response_time_sec REAL CHECK(response_time_sec>=0), hint_count INTEGER CHECK(hint_count>=0), independent_flag INTEGER CHECK(independent_flag IN (0,1)), error_type TEXT, process_code TEXT, FOREIGN KEY(task_id,student_id) REFERENCES task_assignments, FOREIGN KEY(task_id,question_id) REFERENCES task_questions, UNIQUE(student_id,task_id,question_id,attempt_no));
CREATE TRIGGER IF NOT EXISTS response_check BEFORE INSERT ON responses BEGIN
 SELECT CASE WHEN NEW.score>(SELECT max_score FROM questions WHERE question_id=NEW.question_id) THEN RAISE(ABORT,'score exceeds max_score') END;
 SELECT CASE WHEN NEW.submitted_at<(SELECT available_at FROM tasks WHERE task_id=NEW.task_id) THEN RAISE(ABORT,'submitted before available') END;
 SELECT CASE WHEN NEW.submitted_at<(SELECT assigned_at FROM task_assignments WHERE task_id=NEW.task_id AND student_id=NEW.student_id) THEN RAISE(ABORT,'submitted before assigned') END;
 SELECT CASE WHEN (SELECT eligibility_status FROM task_assignments WHERE task_id=NEW.task_id AND student_id=NEW.student_id)!='eligible' THEN RAISE(ABORT,'assignment not eligible') END;
END;
CREATE TABLE IF NOT EXISTS quarantine(id INTEGER PRIMARY KEY, table_name TEXT NOT NULL, line_no INTEGER NOT NULL, reason TEXT NOT NULL, raw_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS analysis_runs(run_id TEXT PRIMARY KEY, created_at TEXT NOT NULL, metadata_json TEXT NOT NULL, result_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_records(review_key TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES analysis_runs, student_id TEXT NOT NULL REFERENCES students, kp_id TEXT NOT NULL REFERENCES knowledge_points, rule_id TEXT NOT NULL, rule_version TEXT NOT NULL, suggestion TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('pending','accepted','modified','deferred')), modified_action TEXT NOT NULL, reviewer_alias TEXT NOT NULL, notes TEXT NOT NULL, updated_at TEXT NOT NULL, synthetic INTEGER NOT NULL CHECK(synthetic=1));
CREATE TABLE IF NOT EXISTS intervention_records(review_key TEXT PRIMARY KEY REFERENCES review_records, plan TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('planned','in_progress','completed','cancelled')), planned_start TEXT, planned_end TEXT, executed_at TEXT, observation TEXT NOT NULL, synthetic INTEGER NOT NULL CHECK(synthetic=1));
CREATE INDEX IF NOT EXISTS responses_time ON responses(submitted_at,student_id);
CREATE INDEX IF NOT EXISTS responses_first ON responses(student_id,task_id,question_id,attempt_no);
CREATE TABLE IF NOT EXISTS question_tags(question_id TEXT PRIMARY KEY REFERENCES questions, domain TEXT NOT NULL CHECK(domain IN ('algebra','geometry')), purpose TEXT NOT NULL CHECK(purpose IN ('foundation','ability_probe')), ability TEXT CHECK(ability IN ('computation','reasoning','application')), prompt TEXT NOT NULL, reference_answer TEXT NOT NULL, tag_version TEXT NOT NULL, CHECK(purpose!='ability_probe' OR ability IS NOT NULL));
CREATE TABLE IF NOT EXISTS teacher_runs(run_id TEXT PRIMARY KEY, created_at TEXT NOT NULL, result_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS teacher_reviews(run_id TEXT NOT NULL REFERENCES teacher_runs, student_id TEXT NOT NULL REFERENCES students, scope TEXT NOT NULL CHECK(scope IN ('student','domain','ability')), scope_key TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('confirm','adjust','observe','defer')), actions_json TEXT NOT NULL, reason TEXT NOT NULL, timing TEXT NOT NULL, updated_at TEXT NOT NULL, synthetic INTEGER NOT NULL CHECK(synthetic=1), PRIMARY KEY(run_id,student_id,scope,scope_key));
